    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    arm_patches = image_patch.find("arm")

    if not man_patches or not arm_patches:
        return image_patch

    man_centers = [(p.left + p.right) / 2, (p.upper + p.lower) / 2 for p in man_patches]
    arm_centers = [(p.left + p.right) / 2, (p.upper + p.lower) / 2 for p in arm_patches]

    man_arm_pairs = sorted(zip(man_centers, arm_centers), key=lambda pair: abs(pair[0][0] - pair[1][0]))

    for man_center, arm_center in man_arm_pairs:
        if abs(man_center[0] - arm_center[0]) < 10 and abs(man_center[1] - arm_center[1]) < 10:
            return man_patches[man_arm_pairs.index((man_center, arm_center))]

    return man_patches[0]

